   "tsl::table::{Slot, first_occupied, next_occupied, entry_at, entry_at_mut}  // crate-internal, bound-free",
   "cxx::string::{StoiError, stoi(&[u8]) -> Result<i32, StoiError>, stoi_with_pos(&[u8]) -> Result<(i32, usize), StoiError>}",
   "cxx::argv::{argc() -> usize, arg_bytes(i: usize) -> Option<Vec<u8>>}",
   "cxx::runtime::{terminate_invalid_argument_stoi() -> !, terminate_out_of_range_stoi() -> !, terminate_logic_error_null_string() -> !}"
