/// A `Hasher` that scrambles its input (Fibonacci multiply + xor-shift finish).
///
/// Useful when keys are integers whose *low* bits carry little entropy, since
/// the table derives a bucket index from the low bits of the hash.
#[derive(Clone, Copy, Debug, Default)]
pub struct MixingHasher {
    inner: IdentityHasher,
}

impl MixingHasher {
    pub fn new() -> MixingHasher {
        MixingHasher {
            inner: IdentityHasher::new(),
        }
    }
}

impl Hasher for MixingHasher {
    fn finish(&self) -> u64 {
        let mut hash = self.inner.finish().wrapping_mul(FIBONACCI);
        hash ^= hash >> 29;
        hash = hash.wrapping_mul(0xbf58_476d_1ce4_e5b9);
        hash ^= hash >> 32;
        hash
    }

    fn write(&mut self, bytes: &[u8]) {
        self.inner.write(bytes);
    }

    fn write_u8(&mut self, value: u8) {
        self.inner.write_u8(value);
    }

    fn write_u16(&mut self, value: u16) {
        self.inner.write_u16(value);
    }

    fn write_u32(&mut self, value: u32) {
        self.inner.write_u32(value);
    }

    fn write_u64(&mut self, value: u64) {
        self.inner.write_u64(value);
    }

    fn write_usize(&mut self, value: usize) {
        self.inner.write_usize(value);
    }

    fn write_i8(&mut self, value: i8) {
        self.inner.write_i8(value);
    }

    fn write_i16(&mut self, value: i16) {
        self.inner.write_i16(value);
    }

    fn write_i32(&mut self, value: i32) {
        self.inner.write_i32(value);
    }

    fn write_i64(&mut self, value: i64) {
        self.inner.write_i64(value);
    }

    fn write_isize(&mut self, value: isize) {
        self.inner.write_isize(value);
    }

    fn write_u128(&mut self, value: u128) {
        self.inner.write_u128(value);
    }

    fn write_i128(&mut self, value: i128) {
        self.inner.write_i128(value);
    }
}

