/// True when `key` is present.
pub fn contains_key(&self, key: &K) -> bool {
    self.find(key).is_some()
}

/// The value stored for `key`.
pub fn get(&self, key: &K) -> Option<&V> {
    let pos = self.find(key)?;
    self.entry_at(pos).map(|entry| &entry.1)
}

/// A mutable reference to the value stored for `key`.
pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
    let pos = self.find(key)?;
    self.entry_at_mut(pos).map(|entry| &mut entry.1)
}

/// The key/value pair stored for `key`.
pub fn get_key_value(&self, key: &K) -> Option<(&K, &V)> {
    let pos = self.find(key)?;
    self.entry_at(pos).map(|entry| (&entry.0, &entry.1))
}

/// Inserts `key`/`value` unless `key` is already present.
///
/// Mirrors `std::unordered_map::insert`: the returned flag is `true` when
/// the entry was inserted and `false` when an equivalent key already
/// existed, in which case the stored value is left untouched.  The returned
/// [`Pos`] designates the entry for `key` either way.
pub fn insert(&mut self, key: K, value: V) -> (Pos, bool) {
    if let Some(pos) = self.find(&key) {
        return (pos, false);
    }
    if self.bucket_count == 0 || self.len + 1 > self.grow_at {
        self.grow();
    }

    let entry = (key, value);
    for _ in 0..MAX_GROW_ATTEMPTS {
        let home = self.home_of(&entry.0);
        if let Some(slot) = self.free_slot_for(home) {
            self.buckets[home].neighbourhood |= 1u32 << (slot - home);
            self.buckets[slot].entry = Some(entry);
            self.len += 1;
            return (slot, true);
        }
        // The neighbourhood is saturated: a bigger table spreads it out.
        self.grow();
    }

    self.overflow.push(entry);
    self.len += 1;
    (self.buckets.len() + self.overflow.len() - 1, true)
}

/// Inserts `key`/`value`, overwriting any previous value.
///
/// Mirrors `std::unordered_map::insert_or_assign`; the flag reports whether
/// a new entry was created.
pub fn insert_or_assign(&mut self, key: K, value: V) -> (Pos, bool) {
    if let Some(pos) = self.find(&key) {
        if let Some(entry) = self.entry_at_mut(pos) {
            entry.1 = value;
        }
        return (pos, false);
    }
    self.insert(key, value)
}

/// Removes `key`, returning its value.
pub fn remove(&mut self, key: &K) -> Option<V> {
    self.remove_entry(key).map(|(_, value)| value)
}

/// Removes `key`, returning the whole pair.
pub fn remove_entry(&mut self, key: &K) -> Option<(K, V)> {
    let pos = self.find(key)?;
    self.len -= 1;
    if pos < self.buckets.len() {
        let home = self.home_of(key);
        debug_assert!(pos >= home && pos - home < NEIGHBOURHOOD_SIZE);
        self.buckets[home].neighbourhood &= !(1u32 << (pos - home));
        self.buckets[pos].entry.take()
    } else {
        // `swap_remove` keeps the overflow list compact; overflow order is
        // unspecified anyway, exactly as in an unordered container.
        Some(self.overflow.swap_remove(pos - self.buckets.len()))
    }
}

/// Doubles the bucket count (or performs the first allocation).
fn grow(&mut self) {
    let bucket_count = if self.bucket_count == 0 {
        INITIAL_BUCKET_COUNT
    } else {
        self.bucket_count
            .checked_mul(2)
            .expect("hopscotch table bucket count overflowed usize")
    };
    self.rehash_to(bucket_count);
}

/// Reallocates to exactly `bucket_count` home buckets and reinserts.
fn rehash_to(&mut self, bucket_count: usize) {
    debug_assert!(bucket_count.is_power_of_two());

    let old_buckets = std::mem::replace(&mut self.buckets, new_buckets(bucket_count));
    let old_overflow = std::mem::take(&mut self.overflow);
    self.bucket_count = bucket_count;
    self.grow_at = grow_threshold(bucket_count, self.max_load_factor);
    self.len = 0;

    for bucket in old_buckets {
        if let Some(entry) = bucket.entry {
            self.place(entry);
        }
    }
    for entry in old_overflow {
        self.place(entry);
    }
}
